    facts:[["Date","18 May 1930"],["Place","Korneuburg · Lower Austria"],["Movement","Heimwehr"],["Federal leader","Richard Steidle"],["Intellectual influence","Othmar Spann circle"],["Rejected","Parliamentary democracy and Marxism"],["Demanded","Authoritarian corporative state"],["Operational test","Pfrimer Putsch · 1931"]]
